using CustomCodeFramework.Workers.Abstractions;using Dhole.Content.Application.Abstractions.Cache;using Dhole.Content.Application.Mappings;using Dhole.Content.Domain.ContentItems.Enums;using Dhole.Content.Persistence.DbContexts;using Microsoft.EntityFrameworkCore;namespace Dhole.Content.Worker.Workers;internal sealed class ContentCacheWarmupWorker(ServiceDbContext db,IContentCacheService cache,ILogger<ContentCacheWarmupWorker> logger):IBackgroundWorker{public string Name=>"content.cache-warmup";public async Task ExecuteAsync(IWorkerExecutionContext context,CancellationToken ct){var published=await db.ContentItems.AsNoTracking().Where(x=>!x.IsDeleted&&x.Status==ContentStatus.Published).OrderByDescending(x=>x.PublishedAtUtc).Take(250).ToListAsync(ct);foreach(var x in published)await cache.SetPublishedContentAsync(x.SiteKey,x.Slug,x.Locale,ContentMappings.ToDto(x),cancellationToken:ct);var menus=await db.NavigationMenus.AsNoTracking().Include(x=>x.Items).Where(x=>!x.IsDeleted&&x.IsActive).ToListAsync(ct);foreach(var x in menus)await cache.SetMenuAsync(x.SiteKey,x.Location,ContentMappings.ToDto(x),cancellationToken:ct);var settings=await db.SiteSettings.AsNoTracking().Where(x=>!x.IsDeleted&&x.IsPublic).ToListAsync(ct);foreach(var group in settings.GroupBy(x=>x.SiteKey))await cache.SetPublicSettingsAsync(group.Key,group.Select(ContentMappings.ToDto).ToArray(),cancellationToken:ct);logger.LogInformation("Content cache warmup completed. Content={ContentCount}, Menus={MenuCount}, Settings={SettingCount}.",published.Count,menus.Count,settings.Count);}}
